/**
 * 本地图片路径工具
 * 所有本地图片都存放在 public/images/ 目录下
 * 在子路径部署（妙搭平台 / GitHub Pages）下自动拼接 basename
 *
 * 修复：GitHub Pages 环境下不使用 resolveAppUrl，因为它会返回妙搭平台格式的路径
 *
 * Storage 优化：同步后 base64 替换为 GitHub 路径（/images/custom/...），
 * 在妙搭平台管理后台，这些图片需要从 GitHub raw URL 加载；
 * 在 GitHub Pages 前台，直接用 basename 拼接即可。
 */

import { scopedStorage } from '@lark-apaas/client-toolkit-lite';
import { resolveAssetUrl, isMiaodaPlatform } from './basename';

const GITHUB_CONFIG_KEY = '__app_ledlight_github_config_v1';

interface GithubRawConfig {
  owner: string;
  repo: string;
  branch: string;
  enabled: boolean;
}

function getGithubRawConfig(): GithubRawConfig | null {
  try {
    const raw = scopedStorage.getItem(GITHUB_CONFIG_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<GithubRawConfig>;
    if (parsed.enabled && parsed.owner && parsed.repo && parsed.branch) {
      return {
        owner: parsed.owner,
        repo: parsed.repo,
        branch: parsed.branch || 'main',
        enabled: true,
      };
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * 获取本地图片的完整 URL
 * @param name 图片文件名，如 'hero-slide-1.jpg'
 * @returns 完整 URL（含 basename 前缀）
 */
export function imgPath(name: string): string {
  if (!name) return name;
  // data: URI (base64 等) 直接返回，不拼接路径
  if (name.startsWith('data:')) return name;
  // 绝对 URL (http/https/ftp 等) 直接返回
  if (/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(name)) return name;
  // blob: URL 直接返回
  if (name.startsWith('blob:')) return name;

  const path = name.startsWith('/') ? name : `/images/${name}`;

  // Storage 优化：GitHub 同步后的自定义图片路径
  // 妙搭平台管理后台 → 用 GitHub raw URL 加载（图片在 GitHub 不在妙搭）
  // GitHub Pages / 本地开发 → 用 basename 拼接（图片和站点同仓库）
  if (path.startsWith('/images/custom/')) {
    const ghConfig = getGithubRawConfig();
    if (isMiaodaPlatform() && ghConfig) {
      // 管理后台：从 GitHub raw 加载
      const rawPath = path.replace(/^\/images\/custom\//, 'images/custom/');
      return `https://raw.githubusercontent.com/${ghConfig.owner}/${ghConfig.repo}/${ghConfig.branch}/${rawPath}`;
    }
    // GitHub Pages 或本地开发：直接用相对路径 + basename
    return resolveAssetUrl(path);
  }

  return resolveAssetUrl(path);
}
